import{_ as e,o as a,c as r,a3 as d}from"./chunks/framework.BZCmpA0A.js";const o="/WUWAOS/assets/wuwaos-xerj-corpus-hub-email-2026-11-05.CouXpDhU.png",u=JSON.parse('{"title":"WUWAOS 實作紀錄","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1794034236000}'),i={name:"index.md"};function l(h,t,s,n,p,c){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="wuwaos-實作紀錄" tabindex="-1">WUWAOS 實作紀錄 <a class="header-anchor" href="#wuwaos-實作紀錄" aria-label="Permalink to &quot;WUWAOS 實作紀錄&quot;">​</a></h1><p>從第一條指令，到能建立行程、編輯檔案的小型作業系統。</p><p>WUWAOS 是以 C 與 RISC-V 組合語言撰寫、真正運行於 QEMU 虛擬電腦上的作業系統。這份文件把設計按照主題整理，連接教科書觀念、目前程式碼與可以親手觀察的操作。</p><p><strong><a href="./topics/getting-started.html">從環境與啟動開始 →</a></strong></p><p>Windows 可先下載 <a href="./portable-windows.html">免安裝完整包</a>，在 PowerShell 使用 <code>.\\Start-WUWAOS.cmd</code> 啟動 CLI，或加上 <code>gui</code> 開啟桌面。最新原始碼的磁碟保護機制與 <code>.\\Test-FsDisk.cmd</code> 操作見 <a href="./SPEC-31-filesystem-initialization-guard.html">Spec 31</a>；使用者已確認磁碟保護驗證，這些後續修正不包含在既有 portable v1 ZIP。</p><h2 id="閱讀路線" tabindex="-1">閱讀路線 <a class="header-anchor" href="#閱讀路線" aria-label="Permalink to &quot;閱讀路線&quot;">​</a></h2><table tabindex="0"><thead><tr><th>想理解什麼</th><th>從這裡開始</th></tr></thead><tbody><tr><td>原始碼如何分層，UI 如何經 TTY 與 kernel 溝通？</td><td><a href="./CODE_GUIDE.html#ui-與-kernel-的資料通道">程式碼架構</a> → <a href="./SPEC-33-module-architecture.html">Spec 33</a></td></tr><tr><td>entry.S 怎麼進入 C，最後顯示提示字元？</td><td><a href="./topics/boot.html">開機流程</a></td></tr><tr><td>桌面圖示如何開啟 GUI shell？</td><td><a href="./topics/boot.html#桌面-terminal-與-gui-shell">開機流程</a></td></tr><tr><td>使用者程式怎麼請核心幫忙？</td><td><a href="./topics/traps.html">例外與系統呼叫</a></td></tr><tr><td>行程如何建立、排程、結束與回收？</td><td><a href="./topics/processes.html">行程管理</a> → <a href="./topics/scheduling.html">計時器與 RR 排程</a></td></tr><tr><td>CPU 如何找到資料，缺頁時發生什麼？</td><td><a href="./topics/memory.html">Sv39</a> → <a href="./topics/paging.html">按需分頁與交換</a></td></tr><tr><td>輸入的文字如何存到磁碟？</td><td><a href="./topics/io.html">輸入輸出</a> → <a href="./topics/filesystem.html">WUFS</a></td></tr><tr><td>如何寫自己的互動程式？</td><td><a href="./topics/applications.html">Shell 與 fan</a></td></tr><tr><td>如何觀察行程的 CPU 與記憶體用量？</td><td><a href="./topics/monitoring.html">workstate 即時監測</a></td></tr></tbody></table><h2 id="目前開發進度" tabindex="-1">目前開發進度 <a class="header-anchor" href="#目前開發進度" aria-label="Permalink to &quot;目前開發進度&quot;">​</a></h2><p>目前以整理核心錯誤處理與共享狀態為主，為後續 UI／視窗功能建立基礎：</p><ul><li><strong>已完成</strong>：多 TTY/session 物件、事件等待，以及 2B1 的 owner-aware kernel gate；OFD／pipe、FS 與 VM 在可合作式切換行程的路徑上有明確的保護範圍。</li><li><strong>暫停於 2B2 前置整理</strong>：Block driver 已改用明確的裝置指標，實際傳輸仍同步輪詢；尚未完成非同步 request、completion event 或非同步 swap 的 PTE 撤銷／回復。</li><li><strong>後續待辦</strong>：GPU 非阻塞 present、裝置復原、資源與堆疊保護、多視窗管理、檔案原子替換與統一診斷。程式實作暫停，先同步文件與網站。</li></ul><p>詳細步驟、演算法及已執行／未執行的驗收見 <a href="https://github.com/johnson931128/WUWAOS/blob/main/plan.md" target="_blank" rel="noreferrer">實作計畫</a>；只看進度可讀 <a href="https://github.com/johnson931128/WUWAOS/blob/main/plan_current.md" target="_blank" rel="noreferrer">精簡清單</a>。這些原始碼更新不包含於既有 portable v1 ZIP。</p><h2 id="目前的系統邊界" tabindex="-1">目前的系統邊界 <a class="header-anchor" href="#目前的系統邊界" aria-label="Permalink to &quot;目前的系統邊界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>項目</th><th>現況</th></tr></thead><tbody><tr><td>平台</td><td>QEMU virt、RV64、單核心、128 MiB RAM</td></tr><tr><td>執行模式</td><td>S-mode 核心、U-mode 使用者程式</td></tr><tr><td>行程</td><td>最多 16 個 PCB；fork／exec／exit／wait 與事件等待</td></tr><tr><td>核心上下文</td><td>RV64 swtch.S；每行程保留 C 呼叫堆疊、獨立排程器堆疊</td></tr><tr><td>同步</td><td>使用者 Mutex／Semaphore；核心 owner-aware gate 保護 OFD／pipe、FS 與 VM</td></tr><tr><td>排程</td><td>單核心 RR、50 ms 時間片；使用者程式可搶占，核心內不被計時器搶占，但可事件等待／合作式切換</td></tr><tr><td>記憶體</td><td>Sv39 三級頁表、4 KiB 頁、按需分頁、FIFO 置換、獨立 Swap</td></tr><tr><td>磁碟</td><td>同步 VirtIO 區塊 I/O；WUFS0002 redo journal／開機重播，逾時仍 fail-stop，尚無裝置復原</td></tr><tr><td>操作</td><td>Shell FD/OFD、三階段管道、檔案重導向、fan 全螢幕文字編輯器</td></tr><tr><td>圖形輸出</td><td>可選 VirtIO GPU/tablet/keyboard；1280×720 桌面含固定 Terminal 視窗與獨立 GUI shell TTY</td></tr><tr><td>監測</td><td>workstate 全螢幕；每秒更新行程、CPU 派發時間、RSS／Swap 與整體 RAM</td></tr></tbody></table><p>這是現有功能的實作紀錄，不是承諾與 Linux 相容。支援受限靜態 RV64 ELF 從 WUFS 載入；尚無通用 ELF／Linux 相容、網路、一般視窗管理或檔案管理器。圖形模式提供一個固定大小的 Terminal 視窗，透過獨立 GUI TTY 接到既有 shell；UART shell 保留於 <code>make run</code>。Terminal 的能力與限制見 <a href="./SPEC-30-graphical-terminal.html">Spec 30</a>，桌面與游標見 <a href="./SPEC-28-native-desktop.html">Spec 28</a>。</p><h2 id="這份文件如何組織" tabindex="-1">這份文件如何組織 <a class="header-anchor" href="#這份文件如何組織" aria-label="Permalink to &quot;這份文件如何組織&quot;">​</a></h2><p>主題章節描述目前設計；<a href="./history.html">原始規格與驗收紀錄</a> 保留開發過程。舊規格中的架構可能已被後續版本取代，閱讀時應留意每份文件的階段說明。</p><p>本站只展示架構說明與操作指令，OS 原始碼以 GitHub 連結提供，不內嵌程式碼。OS 與文件變更經使用者授權提交到 main；網站發布另由專用工具處理。驗收結果是各規格所記錄的當時操作，網站建置不代表重新執行過 OS 驗證。</p><h2 id="特殊事蹟" tabindex="-1">特殊事蹟 <a class="header-anchor" href="#特殊事蹟" aria-label="Permalink to &quot;特殊事蹟&quot;">​</a></h2><p>2026 年 11 月 5 日收到 XERJ Corpus Hub 來信，表示選中 WUWAOS 的非空白磁碟保護實作，擬以 MIT 授權並附來源的方式作為程式參考。</p><p><img src="'+o+'" alt="XERJ Corpus Hub 於 2026 年 11 月 5 日寄出的 WUWAOS 程式參考通知郵件截圖"></p><p><a href="https://raw.githubusercontent.com/johnson931128/WUWAOS/main/docs/images/wuwaos-xerj-corpus-hub-email-2026-11-05.png" target="_blank" rel="noreferrer">查看原圖</a></p><h2 id="參考與致意" tabindex="-1">參考與致意 <a class="header-anchor" href="#參考與致意" aria-label="Permalink to &quot;參考與致意&quot;">​</a></h2><p>閱讀版面與循序章節安排參考 <a href="https://operating-system-in-1000-lines.vercel.app/tw/" target="_blank" rel="noreferrer">《1000 行打造作業系統》</a>。本文內容依 WUWAOS 自己的程式碼整理，沒有複製該書文章。作業系統概念參考 repository 的 <code>notes/</code> 課程筆記，各章另列對應檔案；筆記全文不包含在網站中。</p>',23)])])}const f=e(i,[["render",l]]);export{u as __pageData,f as default};
